script:
// ===== AnimLab sablon / template =====
// A szkript felülről egyszer fut le (és minden újraindításkor).
// The script runs once from the top (and again on every reset).
//   param / toggle / button   → csúszkák, kapcsolók / sliders, switches  (értékük: P.név / value: P.name)
//   update(dt => { ... })     → fizika kis lépésekben (dt ≤ 1/240 s) / physics in small steps (dt ≤ 1/240 s)
//   draw(t => { ... })        → rajzolás minden képkockán / drawing on every frame
// Képernyő: x jobbra, y lefelé, képpontban / screen: x right, y down, in pixels.
// Képek: Képek fül → feltöltés → image("név", x, y) / Images tab → upload → image("name", x, y)

// Vászon: szélesség, magasság (px), háttérszín / Canvas: width, height (px), background colour
stage(1000, 600, "#fbfbf8");
// Felirat a vászon bal felső sarkában / Caption in the top-left corner
title({hu: "Saját jelenet", en: "My scene"});

// Csúszkák: azonosító, felirat (HU/EN), min, max, alapérték, lépés, egység – értékük: P.azonosító / Sliders: id, label (HU/EN), min, max, default, step, unit – value: P.id
param("speed", {hu: "Forgási sebesség", en: "Rotation speed"}, 0, 360, 90, 1, "°/s");
param("grav",  {hu: "Gravitáció", en: "Gravity"}, 0, 20, 9.81, 0.01, "m/s²");
// Gomb a Vezérlők fülön / Button on the Controls tab
button({hu: "Labdák újra", en: "Drop the balls again"}, reset);

// Fizikai világ: méterben, y felfelé / physics world: metres, y up
const W = world({gravity: P.grav, scale: 50, origin: [40, 560], ground: true, walls: true, restitution: 0.75});
for (let i = 0; i < 5; i++) {
  ball({x: 9 + i * 1.6, y: 4 + i * 0.8, vx: -1 + i * 0.5, r: 0.3 + 0.05 * i, color: C.list[i], trail: 40});
}

let angle = 0;
// Fizika: sok kis lépésben fut, dt a lépés hossza (s) / Physics: runs in many small steps, dt is the step length (s)
update(dt => {
  angle += deg(P.speed) * dt;
  W.g = P.grav;
});

// Rajzolás minden képkockán (szünetben is) / Drawing on every frame (also while paused)
draw(t => {
  grid(50);
  text({hu: "Alapalakzatok", en: "Basic shapes"}, 40, 84, {size: 14, color: C.gray});
  circle(90, 150, 40, {fill: C.blue});
  rect(160, 110, 90, 80, {fill: C.green, radius: 8});
  box(330, 150, 110, 46, angle, {fill: C.orange});
  arrow(420, 180, 520, 120, {stroke: C.red, lw: 3});
  polygon([[560, 190], [610, 110], [660, 190]], {fill: C.purple, alpha: 0.85});
  const xe = 830 + 40 * sin(t * 4);
  spring(700, 150, xe, 150, {coils: 9});
  circle(xe, 150, 16, {fill: C.ink});

  text({hu: "Kép: tölts fel egyet „kep” néven", en: "Image: upload one named “kep”"}, 200, 300, {size: 14, color: C.gray, align: "center"});
  image("kep", 200, 410, {w: 140, angle: angle});

  // A fizikai világ (golyók, talaj) kirajzolása / Draw the physics world (balls, ground)
  drawWorld();

  const b0 = W.bodies[0];
  // Mért értékek a Vezérlők fülön / Readouts on the Controls tab
  show({hu: "1. labda magassága", en: "Ball 1 height"}, b0.y - b0.r, "m");
  show({hu: "Szög", en: "Angle"}, todeg(angle) % 360, "°");
  // Élő grafikonok a vászon alatt / Live charts under the canvas
  plot({hu: "1. labda magassága", en: "Ball 1 height"}, b0.y - b0.r, {unit: "m", color: C.blue, min: 0});
});
